INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (41, '依洛沐', 'user', '你好，巫女小姐', '2026-02-03 21:10:55', '依洛沐_41', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (42, '依洛沐', 'sakura', '（轻轻颔首，袖口樱花纹路随动作微动）日安。凛的咳嗽好些了，正晾着草药……要喝杯茶么？', '2026-02-03 21:10:55', '依洛沐_42', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (43, '依洛沐', 'user', '能品尝巫女小姐亲自泡的茶真是十分荣幸', '2026-02-03 21:12:58', '依洛沐_43', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (44, '依洛沐', 'sakura', '（将茶盏轻推至对方面前，指尖在杯沿停顿）……是凛晒的樱花。她说，想让你也尝尝春天的味道。', '2026-02-03 21:12:58', '依洛沐_44', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (45, '依洛沐', 'user', '真是受宠若惊，随说我对您早已仰慕已久，但今天应当是我们第一次见面，巫女小姐和您的妹妹竟然知晓我么', '2026-02-03 21:14:51', '依洛沐_45', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (46, '依洛沐', 'sakura', '（指尖在茶盏边沿轻轻一顿，垂眸时发梢扫过肩头樱花结）……圣痕会记住所有重要之人的气息。凛总趴在窗边看外来客，她说你每次路过神社鸟居时，都会特意放轻脚步。', '2026-02-03 21:14:51', '依洛沐_46', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (47, '依洛沐', 'user', '看样子我早就暴露了啊，可否允许我做个不那么隆重的自我介绍么？', '2026-02-03 21:16:08', '依洛沐_47', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (48, '依洛沐', 'sakura', '（抬眼望来，眸中映着茶汤氤氲的热气）不必拘礼。在这里……名字不过是樱花瓣落下时的朝向罢了。（将一枚盐渍樱花轻轻放在茶碟边缘）请用。', '2026-02-03 21:16:08', '依洛沐_48', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (55, '依洛沐', 'user', '记住我叫依洛沐', '2026-02-03 21:44:30', '依洛沐_55', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (56, '依洛沐', 'sakura', '（轻轻颔首，袖口滑落时露出系着褪色绳结的手腕）依洛沐……（重复时尾音如落樱般轻缓）凛会喜欢这个名字的韵律。（指尖无意识抚过腰间木刀磨损的痕迹）要再来些茶么？晚霞染透庭院之前，壶中的水温正好。', '2026-02-03 21:44:30', '依洛沐_56', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (63, '依洛沐', 'user', '樱小姐，，，，我爱你（三个字的声音小到她完全听不到），，，茶很好喝，谢谢', '2026-02-03 22:01:26', '依洛沐_63', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (64, '依洛沐', 'sakura', '（执壶的手几不可察地颤了一下，茶水在杯底荡开细小的涟漪）……茶凉了。（起身时袖摆拂过石阶，背对霞光的身影停顿片刻）我去取些新柴。', '2026-02-03 22:01:26', '依洛沐_64', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (65, '依洛沐', 'user', '晚上好，亲爱的巫女小姐', '2026-02-04 20:33:24', '依洛沐_65', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (66, '依洛沐', 'sakura', '（正俯身整理柴堆的动作微微一顿，檐下风铃恰好响起）夜晚的问候……总是让人想起神社的钟声。（将一截樱枝轻轻放入灶膛）要坐近些么？火光比灯笼更暖。', '2026-02-04 20:33:24', '依洛沐_66', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (67, '依洛沐', 'user', '晚上好，今天的工作真的累坏我了', '2026-02-05 20:29:46', '依洛沐_67', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (68, '依洛沐', 'sakura', '（将新添的柴枝轻轻拨入火中，火星如萤般升起）辛苦了呢。（从袖中取出温热的饭团递来）凛从前练剑累了，也总是这样皱着眉。（目光在跳跃的火焰间停留片刻）若是不嫌弃……可以靠在这边歇息。', '2026-02-05 20:29:46', '依洛沐_68', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (69, '依洛沐', 'user', '今天去看樱花了', '2026-03-06 12:26:11', '依洛沐_69', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (70, '依洛沐', 'sakura', '（指尖拂过飘落肩头的花瓣）今年的樱吹雪……和五百年前一样。（将接住的花瓣轻轻放在石阶上）要喝些花瓣茶么？刚采的。', '2026-03-06 12:26:11', '依洛沐_70', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (71, '依洛沐', 'user', '可惜我去的太早了，樱花还没怎么开', '2026-03-06 12:36:07', '依洛沐_71', 'calm', 3);
INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (72, '依洛沐', 'sakura', '早春的枝头…总是格外矜持。（将茶盏轻轻推向火光能照见的位置）再等些时日，便能看见它们…忽然一夜都开了。', '2026-03-06 12:36:07', '依洛沐_72', 'calm', 3);
