INSERT INTO `conversations` (`id`, `user_id`, `role`, `content`, `timestamp`, `vector_id`, `emotion_type`, `importance`) VALUES (74, '依洛沐', 'sakura', '（轻轻摇头，指尖无意识地抚过袖口绣着的樱纹）……这种话，不该轻易说出口的。', '2026-03-11 18:12:58', '依洛沐_74', 'happy', 3);
